-- In one BEGIN IMMEDIATE transaction: verify publish_media_cache_eligible.sql returns a row; select expired keys with publish_media_cache_prune_select.sql; delete each using publish_media_cache_prune_delete.sql; execute the guarded upsert below. Bind the same parameters throughout.
INSERT INTO runtime_media_cache(actor_id,bot_id,cache_key,revision,media,expires_at) SELECT ?3,?4,?5,?7,?8,CAST(unixepoch('subsec') * 1000000 AS INTEGER)+(?9*1000000) WHERE EXISTS(SELECT 1 FROM runtime_operations op WHERE op.id=?1 AND op.attempt=?2 AND op.status='succeeded' AND op.actor_id=?3 AND CAST(json_extract(op.request,'$.actor_id') AS TEXT)=CAST(?3 AS TEXT) AND CAST(json_extract(op.request,'$.target.bot_id') AS TEXT)=CAST(?4 AS TEXT) AND op.planned_artifact_count=?6 AND op.delivered_artifact_count=?6 AND op.cancel_requested=0 AND ?6 BETWEEN 1 AND 100 AND NOT EXISTS(SELECT 1 FROM runtime_delivery_units du WHERE du.operation_id=op.id AND du.attempt=op.attempt AND du.status<>'sent') AND COALESCE((SELECT SUM(artifact_count) FROM runtime_delivery_units du WHERE du.operation_id=op.id AND du.attempt=op.attempt AND du.status='sent'),0)=?6 AND op.request=?10 AND op.cache_key=?5) ON CONFLICT(actor_id,bot_id,cache_key) DO UPDATE SET revision=excluded.revision,media=excluded.media,expires_at=excluded.expires_at,created_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) RETURNING 1 AS published;